// conv1d, 'same' padding, ReLU.   in: [n][cin]   out: [n][cout]
static inline void fc_conv(const float *in, int n, int cin, const float *w, const float *b, int k, int cout, float *out) {
    const int pad = (k - 1) / 2;
    for (int t = 0; t < n; t++) {
        for (int o = 0; o < cout; o++) {
            float acc = b[o];
            for (int j = 0; j < k; j++) {
                int s = t + j - pad;
                if (s < 0 || s >= n) continue;
                const float *x = in + s * cin;
                const float *ww = w + (j * cin) * cout + o;
                for (int c = 0; c < cin; c++) acc += x[c] * ww[c * cout];
            }
            out[t * cout + o] = acc > 0.0f ? acc : 0.0f;
        }
    }
}

static inline void fc_pool2(const float *in, int n, int c, float *out) {
    for (int t = 0; t < n / 2; t++)
        for (int o = 0; o < c; o++) {
            float a = in[(2 * t) * c + o], b2 = in[(2 * t + 1) * c + o];
            out[t * c + o] = a > b2 ? a : b2;
        }
}

// win: [FALL_CNN_WIN][FALL_CNN_CH] RAW units (g, deg/s). Returns P(fall) in 0..1.
static inline float echowear_fall_cnn_score(const float *win) {
    static float x[FALL_CNN_WIN * 6];
    static float a1[FALL_CNN_WIN * 24];
    static float p1[(FALL_CNN_WIN / 2) * 24];
    static float a2[(FALL_CNN_WIN / 2) * 32];
    static float p2[(FALL_CNN_WIN / 4) * 32];
    static float a3[(FALL_CNN_WIN / 4) * 48];
    for (int t = 0; t < FALL_CNN_WIN; t++)
        for (int c = 0; c < 6; c++)
            x[t * 6 + c] = (win[t * 6 + c] - FALL_CNN_MEAN[c]) / FALL_CNN_STD[c];
    fc_conv(x, FALL_CNN_WIN, 6, fc_w1, fc_b1, 7, 24, a1);
    fc_pool2(a1, FALL_CNN_WIN, 24, p1);
    fc_conv(p1, FALL_CNN_WIN / 2, 24, fc_w2, fc_b2, 5, 32, a2);
    fc_pool2(a2, FALL_CNN_WIN / 2, 32, p2);
    fc_conv(p2, FALL_CNN_WIN / 4, 32, fc_w3, fc_b3, 3, 48, a3);
    float g[48];
    for (int o = 0; o < 48; o++) {
        float s = 0.0f;
        for (int t = 0; t < FALL_CNN_WIN / 4; t++) s += a3[t * 48 + o];
        g[o] = s / (float)(FALL_CNN_WIN / 4);
    }
    float d[32];
    for (int o = 0; o < 32; o++) {
        float s = fc_db1[o];
        for (int i = 0; i < 48; i++) s += g[i] * fc_d1[i * 32 + o];
        d[o] = s > 0.0f ? s : 0.0f;
    }
    float z = fc_db2;
    for (int i = 0; i < 32; i++) z += d[i] * fc_d2[i];
    return 1.0f / (1.0f + expf(-z));
}
#endif
